from lib import *
S = SS('u149')
steps = [
    step("本机平台:env::consts::OS = macos、FAMILY = unix、ARCH = aarch64;MAIN_SEPARATOR 是 '/',is_separator('/') 为 true、is_separator('\\\\') 为 false。反斜杠在这个平台的路径里只是普通字符:Path::new(\"a\\\\b\\\\c\") 只有 1 个组件,Path::new(\"a/b/c\") 有 3 个;\"C:\\\\dir\\\\file.txt\" 的 file_name 就是整个字符串 —— 在 unix 上 Windows 风格的路径是一个怪异的文件名。", t=tl(S(1)), done=lidx(S(1), 'OS = macos', 'MAIN_SEPARATOR', '反斜杠在本平台', 'file_name'), kv=KV([['macOS 分隔符', '/'], ['反斜杠', '普通字符,不是分隔符']], ['反斜杠'])),
    step("大小写:macOS 默认的 APFS 大小写不敏感但保留大小写。创建 Report.TXT 后,exists 对 Report.TXT、report.txt、REPORT.TXT 都是 true;但 Path::new(\"Report.TXT\") == Path::new(\"report.txt\") 是 false(Path 比较区分大小写);read_dir 返回创建时的大小写 \"Report.TXT\";再写 report.txt 覆盖的是同一个文件(目录里仍只有 1 个);canonicalize 恢复真实大小写。所以不能用 Path 的相等来判断「是不是同一个文件」。", t=tl(S(2)), done=lidx(S(2), 'exists(Report.TXT', 'exists(report.txt', 'exists(REPORT.TXT', 'read_dir', 'canonicalize'), mark=lidx(S(2), 'Path::new("Report.TXT")', '再写 report.txt'), kv=KV([['文件系统', '大小写不敏感,保留大小写'], ['Path ==', '区分大小写']], ['Path =='])),
    step("Unicode 规范化:\"café.txt\" 的 é 可以是 NFC(一个字符 U+00E9,字节 195 169)或 NFD(e + 组合重音 U+0301,字节 101 204 129),两个字符串不相等(false)。用 NFC 名字创建文件后,exists(NFC) 与 exists(NFD) 都是 true —— 文件系统把它们当同一个名字;read_dir 返回的是 NFC 的字节。同一个文件名在字符串比较里不相等,在文件系统里相等。", t=tl(S(3)), done=lidx(S(3), 'NFC 字节', 'NFD 字节', '用 NFC 创建后', 'read_dir 返回', '返回的是 NFC'), mark=lidx(S(3), '两个字符串相等吗'), kv=KV([['字符串 ==', 'NFC ≠ NFD'], ['文件系统', 'NFC 与 NFD 是同一个名字']], ['文件系统'])),
    step("文件名限制:ASCII 文件名最长 255 个字符,256 个失败:InvalidFilename,os error 63(ENAMETOOLONG)。但 100 个汉字(UTF-8 共 300 字节)和 86 个汉字(258 字节)都创建成功 —— 在这个文件系统上限制不是按 UTF-8 字节数算的(其它文件系统例如按字节限制的会不同,没有验证)。路径里含 NUL 字节则是 InvalidInput:file name contained an unexpected NUL byte。", t=tl(S(4)), done=lidx(S(4), '文件名最长', '100 个汉字', '86 个汉字'), mark=lidx(S(4), 'NUL'), kv=KV([['ASCII', '最长 255,256 → os error 63'], ['300 字节的汉字名', '成功(不是按字节限制)'], ['NUL', 'InvalidInput']], ['300 字节的汉字名'])),
    step("写跨平台代码的做法:用 Path::join 或从组件迭代器收集成 PathBuf,而不是拼字符串。本平台上 format!(\"{}/{}\") 与 join 结果相同,但在 Windows 上 join 会用反斜杠;用 cfg(unix) / cfg(windows) 选择平台相关代码时,只有被选中的分支会被编译进二进制。本文只在 macOS 上运行,Windows 与 Linux 的实际行为没有验证。", t=tl(S(5)), done=lidx(S(5), '字符串拼接', '从组件迭代器', 'cfg(unix)'), kv=KV([['拼路径', 'Path::join / collect::<PathBuf>()'], ['平台差异', 'cfg(unix) / cfg(windows)']], ['拼路径'])),
]
A = mkart('u149', 149, 'Rust,跨平台,路径,大小写,Unicode,真实验证,动画演示',
    '在 macOS 上验证路径的跨平台陷阱:反斜杠不是分隔符;APFS 大小写不敏感而 Path 比较区分大小写;NFC 与 NFD 在字符串里不等、在文件系统里是同一个名字;ASCII 文件名最多 255(os error 63)而 300 字节的汉字名可创建;NUL 非法;用 join 拼路径。Windows 与 Linux 的行为没有验证。',
    '同样的路径代码在 macOS、Linux 与 Windows 上可能表现不同。本文只有一台 macOS,所以只验证这台机器上能验证的:分隔符、大小写、Unicode 规范化、文件名限制。每一项都标明「只在 macOS 上验证」,Windows 的盘符与 UNC 等行为明确留作未验证。',
    [('大小写', 'exists 不区分而 Path == 区分的矛盾'), ('255', 'ASCII 文件名最长字符数(os error 63)'), ('NFC ≠ NFD', '字符串比较不等,但文件系统里是同一个文件名')],
    [('平台常量与分隔符', '<p>路径的基础操作见<a href="rust-path-pathbuf.html">Path 与 PathBuf</a>。</p>'), ('大小写', None), ('Unicode 规范化', None), ('文件名限制', None), ('写跨平台代码', '<p>编译期的 cfg 与 build.rs 的关系见<a href="rust-build-rs.html">Build Script build.rs</a>。</p>')],
    steps, [ENV_U + '。macOS(APFS 默认配置)', '没有验证:Windows(盘符、UNC、保留名 CON/NUL、尾部的点与空格、长路径 \\\\?\\ 前缀、UTF-16 编码)、Linux(区分大小写的 ext4、字节为单位的文件名)、macOS 上区分大小写的 APFS 卷、HFS+、网络文件系统;也没有尝试用 --target 交叉编译(本机没有安装其它目标的标准库)'], '跨平台路径')
